using Godot;
using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
public partial class NewGameFrontEnd
{
 const int UnitDeadlineCheckpoints=12;
 bool DeadlineHeld=>FlowCase is "deadline-held" or "deadline-closed";
 bool DeadlineSuccess=>FlowCase is "deadline-time" or "deadline-held";
 void IssueDeadline(long deadline){var s=game!.Session;var result=s.DecideNewMilitary(new(new("request:deadline-check/"+s.Revision),NewMilitaryAction.RemoteRecall){DeliverBy=deadline,OriginalPolicy=NewGameMilitary.UnitCommandHoldingContract,PostPolicy=NewGameMilitary.UnitReplyRecoveryContract},s.PlayerControl,s.Revision);Check(result.Code==ResultCode.Accepted,"same real session accepts explicit immutable deadline input");game.Refresh();}
 async Task UnitDeadlineStep(int n){await Frame();var s=game!.Session;
  if(n==1){var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());game.ExerciseMilitaryLine(new(a.X+20000,a.Y),new(a.X+20000,a.Y+12000));game.Advance(ArmyEnd()+1);}
  if(n==2){if(DeadlineHeld)game.ChooseMilitary(NewMilitaryAction.Recall);game.ChooseMilitary(NewMilitaryAction.Handoff);game.ChooseMilitary(NewMilitaryAction.Withdraw);}
  if(n==3)game.Advance(PersonalEnd()+1);
  if(n==4){var w=s.DiagnosticSnapshot();var from=NewGameMilitary.PersonPosition(w,s.Seconds);var to=w.NewMilitary!.Withdrawal!.Sightings.Last().Position;var path=RegionalGround.Plan(from,to,s.Seconds,courier:true,atlas:true);long due=Math.Max(s.Seconds+1,path.LastOrDefault()?.EndAt??0);if(DeadlineHeld){var back=RegionalGround.Plan(to,from,due,courier:true,atlas:true);IssueDeadline(Math.Max(due+1,back.LastOrDefault()?.EndAt??0)+(FlowCase=="deadline-held"?1:0));}else IssueDeadline(due+(FlowCase=="deadline-expired"?-1:0));}
  if(n==5){game.Advance(OriginalCommand().DueAt);var w=s.DiagnosticSnapshot();var r=OriginalCommandFailure();Check(r.Delivered==(FlowCase=="deadline-time"),"actual receipt is valid at T and invalid after T");Check(r.ArrivalStatus==(FlowCase=="deadline-time"?AttemptStatus.Delivered:DeadlineHeld?AttemptStatus.Lost:AttemptStatus.Rejected),"saved initial common attempt status distinguishes absent receiver and expired receipt");Check(!MessageFlow.Knows(w.Messaging,r.ReplyMessage,w.PlayerControl.Value),"sender does not learn hidden receipt outcome before physical report");}
  if(n==6){game.Advance(OriginalCommandFailure().ReplyDueAt);var w=s.DiagnosticSnapshot();if(FlowCase!="deadline-time")Check(MessageFlow.FailureKnown(w.Messaging,OriginalCommand().Attempt,w.PlayerControl.Value),"only returned physical report makes initial failure known");}
  if(n==7){if(FlowCase=="deadline-held")game.ChooseMilitary(NewMilitaryAction.DeliverHeldRecallHome);if(FlowCase=="deadline-closed"){var w=s.DiagnosticSnapshot();Check(!NewGameMilitary.HeldAllowed(w,NewMilitaryAction.DeliverHeldRecallHome)&&!NewGameMilitary.UnitRetryAllowed(w,NewMilitaryAction.RetryRecallHome),"expired authored deadline cannot be extended through visible handover or retry");string hash=ContractJson.CanonicalHash(w);var result=s.DecideNewMilitary(new(new("request:expired-check/"+s.Revision),NewMilitaryAction.DeliverHeldRecallHome),s.PlayerControl,s.Revision);Check(result.Code==ResultCode.NotAvailable&&hash==ContractJson.CanonicalHash(s.DiagnosticSnapshot()),"expired request rejected atomically");}}
  if(n==8&&FlowCase=="deadline-held"){game.Advance(s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last().DueAt);var w=s.DiagnosticSnapshot();var m=w.Messaging.Messages.Single(m=>m.Id==OriginalCommand().Message);Check(s.Seconds==m.DeliverBy&&OriginalCommandLate().Received,"held physical original arrives exactly at unchanged deadline");Check(!w.NewMilitary!.Withdrawal!.Receipts.Single().Delivered,"late receipt never rewrites initial loss");}
  if(n==9&&FlowCase=="deadline-held"){game.Advance(OriginalCommandLate().DueAt);Check(MessageFlow.Knows(s.DiagnosticSnapshot().Messaging,OriginalCommandLate().ReplyMessage!,s.PlayerControl.Value),"acknowledgement may arrive after original receipt deadline");}
  if(n==10&&DeadlineSuccess){game.Advance(Math.Max(s.Seconds,ArmyEnd()+1));game.ChooseMilitary(NewMilitaryAction.Attach);game.ChooseMilitary(NewMilitaryAction.Reclaim);game.ChooseMilitary(NewMilitaryAction.Enter);game.ChooseMilitary(NewMilitaryAction.Unload);game.ChooseMilitary(NewMilitaryAction.Report);game.ChooseMilitary(NewMilitaryAction.Return);}
  if(n==11){game.Advance(s.Seconds+3);OpenAllServiceLetters();var w=s.DiagnosticSnapshot();if(DeadlineSuccess)Check(w.NewMilitary!.Events.Any(e=>e.Effect==MilitaryEffect.Returned),"timely receipt continues through real stock and command handover");else Check(!w.Messaging.Receipts.Any(r=>r.MessageId==OriginalCommand().Message),"expired original never obtains a fabricated formal receipt");game.Press("military-frame");}
  game.Press("save");game.Refresh();
 }
 async Task BeginUnitDeadlineContinuation(){for(int n=1;n<=7;n++)await MilitaryStep(n);for(int n=0;n<UnitDeadlineCheckpoints;n++){await UnitDeadlineStep(n);game!.SaveCheckpoint("unitdeadline"+n);await Capture("s"+n,true);}await Capture("final",true);}
 async Task RestoreUnitDeadline(){Press("load-list");await Frame();string id=File.ReadAllText(Path.Combine(TestOutput,"campaign-instance.txt"));savedList.Select(Array.FindIndex(savedRows,r=>r.Profile.Instance==id));Press("load");await Frame();for(int n=0;n<UnitDeadlineCheckpoints;n++){game!.LoadCheckpoint("unitdeadline"+n);await Frame();await Frame();Check(game.Pose()==File.ReadAllText(Path.Combine(TestOutput,"s"+n+"-pose.json")),"actual deadline/person/unit/courier pose restored at"+n);await Capture("restored-s"+n,true);for(int next=n+1;next<UnitDeadlineCheckpoints;next++)await UnitDeadlineStep(next);Check(ContractJson.CanonicalHash(game.Session.DiagnosticSnapshot())==File.ReadAllText(Path.Combine(TestOutput,"final-world.sha256")),"same inclusive-deadline/late/retry/report future from"+n);await Capture("continued-s"+n,true);GD.Print("UNIT_DEADLINE_RESTORED "+n);}}
 async Task RunUnitDeadlineChecks(){if(OS.GetCmdlineUserArgs().Contains("--new-game-restore"))await RestoreUnitDeadline();else await BeginNewMilitaryFlow();if(OS.GetCmdlineUserArgs().Contains("--unit-deadline-film")){game!.LoadCheckpoint("unitdeadline4");game.Press("auto");string dir=Path.Combine(TestOutput,"film");Directory.CreateDirectory(dir);for(int n=0;n<180;n++){await Frame();ViewportCapture.Save(GetViewport(),Path.Combine(dir,"deadline-"+n.ToString("D3")+".png"));}game.Press("pause");}File.WriteAllText(Path.Combine(TestOutput,OS.GetCmdlineUserArgs().Contains("--new-game-restore")?"restore-checks.json":"check-checks.json"),System.Text.Json.JsonSerializer.Serialize(assertions));GD.Print("UNIT_DEADLINE_PASSED "+FlowCase);}
}
